import {
  Body,
  Controller,
  Delete,
  Get,
  Inject,
  Param,
  Post,
  Put,
  Query,
} from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import {
  AddWishlistItemDto,
  SyncWishlistDto,
  ToggleWishlistItemDto,
  WishlistLookupDto,
  WishlistTokenDto,
} from '../../../libs/dto/orders/wishlist.dto.js';
import { sendRpc } from '../../../libs/rpc/rpc-client.util.js';
import { Public } from '../auth/decorators/public.decorators.js';

/**
 * Storefront wishlist. The wishlist token is generated by the browser and
 * persists in localStorage, so guest saves survive reloads and are linked to
 * the customer once they sign in.
 */
@Public()
@Controller('wishlist')
export class WishlistController {
  constructor(
    @Inject('ORDERS_SERVICE')
    private readonly ordersClient: ClientProxy,
  ) {}

  private call<T>(cmd: string, payload: unknown): Promise<T> {
    return sendRpc<T>(this.ordersClient, cmd, payload);
  }

  @Get()
  get(@Query() query: WishlistLookupDto) {
    return this.call('wishlist.get', query);
  }

  /** Replace the whole list (used to push a browser wishlist to the server). */
  @Put()
  sync(@Body() data: SyncWishlistDto) {
    return this.call('wishlist.sync', data);
  }

  @Post('items')
  addItem(@Body() data: AddWishlistItemDto) {
    return this.call('wishlist.addItem', data);
  }

  /** Heart-button behaviour: add when missing, remove when already saved. */
  @Post('toggle')
  toggle(@Body() data: ToggleWishlistItemDto) {
    return this.call('wishlist.toggle', data);
  }

  @Delete('items/:productId')
  removeItem(
    @Param('productId') productId: string,
    @Query() query: WishlistTokenDto,
  ) {
    return this.call('wishlist.removeItem', {
      wishlistToken: query.wishlistToken,
      productId,
    });
  }

  @Delete()
  clear(@Query() query: WishlistTokenDto) {
    return this.call('wishlist.clear', query);
  }
}
